using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public sealed partial class DemoWorld
{
 public bool TransferUtilityFleetCargo(string id,string resource,int quantity,bool toFleet){var w=Wingmates.FirstOrDefault(w=>w.Id==id&&w.Fleet&&w.Hull>0);var t=Targets.FirstOrDefault(t=>t.Id==id&&t.Alive);if(w==null||t==null||quantity<=0||Vector3.Distance(Player.Position,t.Position)>2500||!InventoryIds.Contains(resource))return false;float available=toFleet?ItemCount(resource,false):w.UtilityCargo.GetValueOrDefault(resource);if(available<quantity)return false;if(toFleet){var ship=t.Profile!;float volume=w.UtilityCargo.Sum(x=>x.Value*ItemVolume(x.Key));if(volume+quantity*ItemVolume(resource)>ship.CargoMax)return false;ChangeStack(resource,false,-quantity);w.UtilityCargo[resource]=w.UtilityCargo.GetValueOrDefault(resource)+quantity;}else{if(CargoUsed+quantity*ItemVolume(resource)>Player.CargoMax)return false;w.UtilityCargo[resource]-=quantity;ChangeStack(resource,false,(decimal)(quantity));}return true;}
 public bool CompressUtilityFleet(string id,string resource,int quantity){var w=Wingmates.FirstOrDefault(w=>w.Id==id&&w.Fleet&&w.Hull>0);var t=Targets.FirstOrDefault(t=>t.Id==id&&t.Alive);if(w==null||t==null||quantity<=0||!IndustrialCore||w.UtilityCargo.GetValueOrDefault(resource)<quantity)return false;string family=resource switch{"ore"=>"Asteroid Ore","deepore"=>"Deep Ore","moonore"=>"Moon Ore","gas"=>"Gas","ice"=>"Ice",_=>""};if(!Player.Utilities.Any(s=>s.Active&&s.Effective&&s.Definition?.Kind=="Compress"&&s.Definition.Family==family&&Vector3.Distance(t.Position,Player.Position)<=s.Definition.Range))return false;w.UtilityCargo[resource]-=quantity;w.UtilityCargo["compressed_"+resource]=w.UtilityCargo.GetValueOrDefault("compressed_"+resource)+quantity;return true;}
}
